   677	    @Environment(TemplateStore.self) var templateStore
   678	    @State private var text: String = ""
   679	    @State private var linePositions: [CGFloat] = []
   680	    @State private var scrollOffset: CGFloat = 0
   681	    @State private var selectedText: String = ""
   682	    @State private var selectedLineRange: String = ""
   683	    var onSelectionChange: ((URL, String, String) -> Void)?
   684	
   685	    private var currentNoteTitle: String {
   686	        guard store.currentIndex >= 0,
   687	              store.currentIndex < store.openFiles.count else { return "" }
   688	        return store.openFiles[store.currentIndex].url
   689	            .deletingPathExtension().lastPathComponent
   690	    }
   691	
   692	    private var currentNoteURL: URL? {
   693	        guard store.currentIndex >= 0,
   694	              store.currentIndex < store.openFiles.count else { return nil }
   695	        return store.openFiles[store.currentIndex].url
   696	    }
   697	
   698	    var body: some View {
   699	        HStack(spacing: 0) {
   700	            // Editor
   701	            HStack(spacing: 0) {
   702	                LineNumberGutter(linePositions: linePositions, scrollOffset: scrollOffset)
   703	                    .frame(width: 44)
   704	                    .background(Color(.textBackgroundColor))
   705	
   706	                MarkdownEditor(
   707	                    text: $text,
   708	                    scrollOffset: $scrollOffset,
   709	                    linePositions: $linePositions,
   710	                    selectedText: $selectedText,
   711	                    selectedLineRange: $selectedLineRange,
   712	                    store: store,
   713	                    templateStore: templateStore
   714	                )
   715	                .background(Color(.textBackgroundColor))
   716	            }
   717	
   718	            // Backlinks right sidebar
   719	            if store.showBacklinks {
   720	                Divider()
   721	
   722	                ScrollView {
   723	                    VStack(spacing: 0) {
   724	                        BacklinksSection(
   725	                            noteTitle: currentNoteTitle,
   726	                            backlinkIndex: store.backlinkIndex,
   727	                            onNavigate: { url in store.open(url) }
   728	                        )
   729	
   730	                        RelatedNotesSection(
   731	                            noteTitle: currentNoteTitle,
   732	                            noteURL: currentNoteURL,
   733	                            backlinkIndex: store.backlinkIndex,
   734	                            tagIndex: store.tagIndex,
   735	                            onNavigate: { url in store.open(url) }
   736	                        )
   737	                    }
   738	                }
   739	                .frame(width: 260)
   740	                .background(Color(.textBackgroundColor).opacity(0.5))
   741	            }
   742	        }
   743	        .onChange(of: selectedText) { _, _ in
   744	            publishSelectionContext()
   745	        }
   746	        .onChange(of: selectedLineRange) { _, _ in
   747	            publishSelectionContext()
   748	        }
   749	        .onChange(of: store.currentIndex) { _, _ in loadText() }
   750	        .onChange(of: store.openFiles[safe: store.currentIndex]?.content.string) { _, newValue in
   751	            // Reload when file content changes externally (e.g., Kiro agent edit)
   752	            if let newValue, newValue != text {
   753	                text = newValue
   754	            }
   755	        }
   756	        .onChange(of: text) { _, _ in saveText() }
   757	        .onAppear { loadText() }
