/// Unified indexer that reads files once and provides content to all indexes.
/// This eliminates the 4x redundant file reads during workspace scanning.
enum UnifiedIndexer {
    /// Represents a file with its pre-read content.
    struct FileContent {
        let url: URL
        let content: String
    }

    /// Result of a unified workspace scan.
    struct ScanResult {
        let tree: [FileTreeNode]
        let media: [URL]
        let fileContents: [FileContent]
    }

    private static let searchableExtensions: Set<String> = ["md", "txt"]

    /// Performs a unified workspace scan that reads all file contents once.
    /// Should be called from a background thread.
    static func scanWorkspace(at workspace: URL) -> ScanResult {
        let tree = FileTreeNode.scan(workspace)
        let media = MediaManager.screenshotURLs(in: workspace)
        let fileContents = readAllFileContents(from: tree)
        return ScanResult(tree: tree, media: media, fileContents: fileContents)
    }

    /// Async version of unified workspace scan.
    static func scanWorkspaceAsync(at workspace: URL) async -> ScanResult {
        await Task.detached(priority: .userInitiated) {
            scanWorkspace(at: workspace)
        }.value
    }

    /// Reads all searchable file contents from the file tree in a single pass.
    private static func readAllFileContents(from tree: [FileTreeNode]) -> [FileContent] {
        let files = flattenSearchableFiles(tree)
        return files.compactMap { node -> FileContent? in
            guard let content = try? String(contentsOf: node.url, encoding: .utf8) else {
                return nil
            }
            return FileContent(url: node.url, content: content)
        }
    }

    /// Flattens the file tree to get all searchable files (md, txt).
    private static func flattenSearchableFiles(_ nodes: [FileTreeNode]) -> [FileTreeNode] {
        var result: [FileTreeNode] = []
        for node in nodes {
            if !node.isDirectory {
                let ext = node.url.pathExtension.lowercased()
                if searchableExtensions.contains(ext) {
                    result.append(node)
                }
            }
            if let children = node.children {
                result.append(contentsOf: flattenSearchableFiles(children))
            }
        }
        return result
    }
}
